import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def check_equality(k, n):
    # x_k = lcm(k, k+1, ..., k+n-1)
    set_k = list(range(k, k + n))
    x_k = list_lcm(set_k)

    # x_{k+1} = lcm(k+1, ..., k+n)
    set_k_plus_1 = list(range(k + 1, k + n + 1))
    x_k_plus_1 = list_lcm(set_k_plus_1)

    return x_k_plus_1 == x_k, x_k, x_k_plus_1

# Investigate for n >= 3 and small k
N_max = 6
K_max = 50

print("--- Results for x_{k+1} = x_k ---")
print(f"Testing N up to {N_max} and K up to {K_max}\n")

for n in range(3, N_max + 1):
    print(f"==================== N = {n} ====================")
    equalities_found = []
    for k in range(1, K_max + 1):
        equal, x_k, x_k_plus_1 = check_equality(k, n)
        if equal:
            equalities_found.append(k)
