import math
from functools import reduce

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def calculate_lcm_sequence(k, n):
    if n == 0:
        return None
    if n == 1:
        return k

    numbers = range(k, k + n)
    return reduce(lcm, numbers)

# Test cases requested: n=1, 2, 3, 4, for k=1, 2, 3, 4
N_values = [1, 2, 3, 4]
K_values = [1, 2, 3, 4]
results = {}

for n in N_values:
    results[n] = {}
    print(f"--- Testing n = {n} ---")
    for k in K_values:
        x_k = calculate_lcm_sequence(k, n)
        x_k_plus_1 = calculate_lcm_sequence(k+1, n)

        is_strictly_increasing = x_k_plus_1 > x_k

        results[n][k] = {
            "x_k": x_k,
            "x_k_plus_1": x_k_plus_1,
            "strictly_increasing": is_strictly_increasing
        }

        print(f"k={k}: x_k = {x_k}, x_{k+1} = {x_k_plus_1}. Strictly Increasing? {is_strictly_increasing}")

print("\n--- Summary Results (for documentation) ---")
for n, k_results in results.items():
    print(f"n={n}: {k_results}")
